import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Conditional Rendering', () => {
  test('Initially shows "Please log in"', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#status');
if (!el) throw new Error('No #status element');
if (!el.textContent.includes('Please log in'))
  throw new Error('Should show "Please log in" initially');
  });

  test('Shows Log In button when logged out', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#login-btn');
if (!btn) throw new Error('No #login-btn found');
if (!btn.textContent.includes('Log In'))
  throw new Error('Button should say "Log In"');
  });

  test('Clicking Log In shows "Welcome back!"', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#login-btn');
btn.click();
await tick();
const el = root.querySelector('#status');
if (!el.textContent.includes('Welcome back!'))
  throw new Error('Should show "Welcome back!" after login');
  });

  test('Shows Log Out button when logged in', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#logout-btn');
if (!btn) throw new Error('No #logout-btn found after login');
  });

  test('Badge with "Online" appears when logged in', async () => {
    const { container: root } = render(<App />);
    const badge = root.querySelector('#badge');
if (!badge) throw new Error('No #badge found when logged in');
if (!badge.textContent.includes('Online'))
  throw new Error('Badge should contain "Online"');
  });

  test('Clicking Log Out returns to logged-out state', async () => {
    const { container: root } = render(<App />);
    const logoutBtn = root.querySelector('#logout-btn');
logoutBtn.click();
await tick();
const el = root.querySelector('#status');
if (!el.textContent.includes('Please log in'))
  throw new Error('Should return to "Please log in" after logout');
const badge = root.querySelector('#badge');
if (badge) throw new Error('Badge should not be visible when logged out');
  });
});
